  "thankYou.unverified.notVerified": "Stripe એ આ ચેકઆઉટ સેટ કરવાનું હજુ પૂરું કર્યું નથી. તમારું પેમેન્ટ સુરક્ષિત છે — કંઈ બે વાર ચાર્જ થયું નથી. અમે તપાસતા રહીશું.",
