  "subscribe.trialEligible": "પાત્ર નવા ગ્રાહકોને એક 7-દિવસની મફત ટ્રાયલ મળે છે. આજે તમને ચાર્જ થશે નહીં — તમારું {price} નું પહેલું પેમેન્ટ ટ્રાયલ પૂરી થાય ત્યારે બાકી થશે, સિવાય કે તમે પહેલા રદ કરો.",
