  "plans.mobileIncludedNote": "બંને વેબસાઇટ પ્લાનમાં મોબાઇલ સાથી સામેલ છે, તેથી વેબસાઇટ સબસ્ક્રાઇબર ક્યારેય તેની સાથે માસિક મોબાઇલ ફી પણ ચૂકવતો નથી.",
  "plans.priceNote": "Essentials $14.99/માસ વત્તા લાગુ પડતા કર, જો કોઈ હોય તો. Business $29.99/માસ વત્તા લાગુ પડતા કર, જો કોઈ હોય તો. કોઈ જરૂરી કર પ્રોવાઇડર ચેકઆઉટ દરમિયાન નક્કી થાય છે અને પેમેન્ટ પહેલા અંતિમ કુલ રકમમાં દેખાવો જોઈએ. આ સરખામણી પેજ કર ક્વોટ કે પેમેન્ટ અધિકૃતતા નથી.",
  "plans.mobilePriceNote": "મોબાઇલ-માત્ર પ્લાન તેની ઇચ્છિત US બેઝ કિંમતે $4.99/માસ છે. App Store કે Google Play ખરીદી પહેલા વાસ્તવિક સ્થાનિક સબસ્ક્રિપ્શન કિંમત અને લાગુ પડતા કર બતાવે છે. તેની પ્રોડક્ટ, સાઇટ અને સ્ટાફ મર્યાદાઓ લોન્ચ સમયે નક્કી થાય છે, વેબસાઇટ સ્તરોથી અલગ.",
  "plans.planChangeNote": "વેબસાઇટ પ્લાન ફેરફાર બિલિંગ પ્રોવાઇડર દ્વારા પુષ્ટિ થવો જોઈએ. નવી કિંમત, અસરકારક તારીખ અને કોઈ પ્રોરેશન ફેરફાર અધિકૃત કરતા પહેલા સમજાવવામાં આવશે. અપગ્રેડથી બીજું સબસ્ક્રિપ્શન બનવું જોઈએ નહીં.",
  "plans.providerNote": "કિંમતો, ચાર્જ અને ટ્રાયલ તમે જે પ્રોવાઇડરથી સબસ્ક્રાઇબ કરો છો તેના દ્વારા સંભાળાય છે — App Store, Google Play, વેબસાઇટ કે Shopify — આ પેજ દ્વારા ક્યારેય નહીં.",
  "plans.reviewBefore": "સબસ્ક્રાઇબ કરતા પહેલા, કૃપા કરીને જુઓ",
