  "plans.trialEndReminder": "તમારી નોંધાયેલી ટ્રાયલ સમાપ્તિ {date} છે. નીચેની રદ કરવાની શરતો જુઓ. આ રીમાઇન્ડર નિર્ધારિત ચાર્જ કે પેમેન્ટ પદ્ધતિ ફાઇલ પર છે તેની પુષ્ટિ કરતું નથી.",
