  "plans.priceNoteGrandfathered": "ફક્ત સૂચિબદ્ધ પ્લાન કિંમત — તમારી મફત પ્રી-લોન્ચ પ્રવેશ માટે ચાર્જ થતો નથી.",
  "plans.priceNoteStandard": "સૂચિબદ્ધ પ્લાન કિંમત વત્તા લાગુ પડતા કર, જો કોઈ હોય તો. ચાર્જ પહેલા તમારો પ્રોવાઇડર કુલ રકમની પુષ્ટિ કરે છે.",
