  "upgrade.taxNote": "વત્તા લાગુ પડતા કર, જો કોઈ હોય તો. ચાર્જ મંજૂર કરતા પહેલા પ્રોવાઇડરે તમારો ચોક્કસ કુલ બતાવવો જ જોઈએ.",
