  "upgrade.downgradeWarning2": "વધારાના વ્યવસાયો અને સ્ટોર (2, 3, 4, 5 — પહેલા સિવાય ગમે તેટલા) હવે ઉપલબ્ધ નથી.",
  "upgrade.downgradeWarning3": "એક્સપોર્ટ જતું રહે છે — CSV/Excel એક્સપોર્ટ નહીં, ફક્ત ઇમ્પોર્ટ.",
  "upgrade.downgradeWarning4": "Bundles અને Suppliers પેજ જતા રહે છે, સાથે અન્ય Business-માત્ર પેજ પણ.",
  "upgrade.downgradeWarning5": "ઇન્વેન્ટરી પોતે સરળતાથી Essentials માં જાય છે — તમે સ્ટોક કરેલું કંઈ કાઢી નખાતું નથી.",
  "upgrade.dialogUpgradeDesc": "તમારી ટ્રાયલ અને સબસ્ક્રિપ્શન તે જ સબસ્ક્રિપ્શન પર રહે છે — બીજું સબસ્ક્રિપ્શન નહીં, નવી ટ્રાયલ નહીં.",
  "upgrade.dialogDowngradeDesc": "ડાઉનગ્રેડ કરવાથી ક્યારેય તમારો ડેટા કાઢી નખાતો નથી — પણ તેનો કેટલોક ભાગ અપ્રાપ્ય બને છે. પહેલા આ વાંચો.",
  "upgrade.gettingQuote": "તમારો ક્વોટ મેળવી રહ્યા છીએ…",
  "upgrade.doneUpgrade": "તમે હવે Business પર છો.",
  "upgrade.doneDowngrade": "ડાઉનગ્રેડ નિર્ધારિત થયું.",
  "upgrade.doneTrial": "તમારી ટ્રાયલ {trialEnds} સુધી ચાલુ રહે છે, પછી Business $29.99/માસથી શરૂ થાય છે. તમારો પહેલો Business ચાર્જ {firstCharge} ના રોજ છે.",
  "upgrade.doneUpgradeNow": "Business હવેથી $29.99/માસથી શરૂ થાય છે. કિંમતનો તફાવત તમારા આગલા ઇન્વોઇસ પર આવશે — તાત્કાલિક ચાર્જ નહીં.",
  "upgrade.doneDowngradeBody": "તમે {date} સુધી Business રાખો છો, પછી Essentials $14.99/માસથી શરૂ થાય છે. ડાઉનગ્રેડ માટે કોઈ રિફંડ નથી.",
  "upgrade.planChangeNotCompleted": "પ્લાન ફેરફાર પૂરો થયો નથી.",
  "upgrade.planChangeFallback": "કંઈ બદલાયું નથી. કૃપા કરીને ફરી પ્રયાસ કરો.",
  "upgrade.quoteFailed": "પ્લાન ફેરફારનો ક્વોટ મેળવી શકાયો નહીં. કંઈ બદલાયું નથી.",
  "upgrade.confirmFailed": "પ્લાન ફેરફાર પૂરો થઈ શક્યો નહીં. કંઈ બદલાયું નથી.",
  "upgrade.previewFrom": "થી",
  "upgrade.previewTo": "સુધી",
  "upgrade.previewEffective": "અસરકારક",
  "upgrade.previewFirstCharge": "નવી કિંમતે પહેલો ચાર્જ",
  "upgrade.previewTrialEnds": "ટ્રાયલ પૂરી થાય છે (બદલાયેલ નથી)",
  "upgrade.previewToValue": "{name} — {price}/માસ",
  "upgrade.previewUpgradeNote": "અપગ્રેડ કરવાથી ક્યારેય તમારી મફત ટ્રાયલ ફરી શરૂ થતી નથી, અને તે ક્યારેય બીજું સબસ્ક્રિપ્શન બનાવતું નથી.",
  "upgrade.previewDowngradeNote": "ડાઉનગ્રેડ તમારા ચૂકવેલા સમયગાળાના અંતે અસરકારક થાય છે. તમારો ગુમાવેલી-સુવિધાનો ડેટા રાખવામાં આવે છે પણ અપ્રાપ્ય બને છે — ડાઉનગ્રેડની આડઅસર તરીકે તે ક્યારેય કાઢી નખાતો નથી.",
  "upgrade.keepMyPlan": "મારો પ્લાન રાખો",
