  "billing.readiness.inspect": "ચેકઆઉટ તૈયારી તપાસો (કોઈ ચાર્જ નહીં)",
  "billing.readiness.unknown": "ફક્ત-વાંચવા તપાસ તૈયારી સ્થાપિત કરી શકી નહીં ({state}). કંઈ બદલાયું નથી.",
  "billing.readiness.ready": "Stripe ચેકઆઉટ તૈયાર છે — કી, વેબહુક ચકાસણી અને પ્રમાણપત્રો બધા પુષ્ટિ થયા છે.",
  "billing.readiness.complimentaryProtected": "તમારું મફત Business વર્કસ્પેસ સુરક્ષિત છે. તે ચૂકવેલું Essentials ટેસ્ટ એકાઉન્ટ બનવું જોઈએ નહીં.",
  "billing.readiness.environmentIncomplete": "Stripe ચેકઆઉટ ઓળખપત્ર, વેબહુક ચકાસણી કે એપ પરત સરનામું બધા પુષ્ટિ થઈ શક્યા નહીં. કોઈ ચેકઆઉટ શરૂ થઈ શકે નહીં.",
  "billing.readiness.ownerHasHistory": "આ માલિક પાસે અગાઉના સબસ્ક્રિપ્શન કે ટ્રાયલના પુરાવા છે. બીજું ચેકઆઉટ બનાવવું જોઈએ નહીં.",
  "billing.readiness.trialAlreadyUsed": "પરિચય ટ્રાયલ પહેલેથી વપરાઈ ગઈ છે કે આરક્ષિત છે. કોઈ પુનરાવર્તિત ટ્રાયલ શરૂ થઈ શકે નહીં.",
  "billing.readiness.trialEligibilityUnverified": "આ માલિક માટે એક વખતની ટ્રાયલ પાત્રતા ચકાસાઈ નથી. ચેકઆઉટ બ્લોક રહે છે.",
  "billing.readiness.testModeUnverified": "એકાઉન્ટ રેકોર્ડ વાંચી શકાય છે, પણ સુરક્ષિત Stripe ટેસ્ટ-મોડ નિયંત્રણ અને ચૂકવેલા-રિન્યુઅલ પૂર્ણતા ચકાસાઈ નથી. ચેકઆઉટ બ્લોક રહે છે.",
