  "billing.readiness.billingHistoryIncomplete": "સંપૂર્ણ માલિક ઇતિહાસ ચકાસી શકાયો નહીં. કોઈ ચેકઆઉટ શરૂ થઈ શકે નહીં.",
  "billing.readiness.ownershipMismatch": "કોઈપણ સબસ્ક્રિપ્શન શરૂ થઈ શકે તે પહેલા એકાઉન્ટ માલિકી કે બિલિંગ રેકોર્ડની સમીક્ષા જરૂરી છે.",
  "billing.readiness.catalogUnverified": "મંજૂર $14.99/માસ સર્વર ચેકઆઉટ વ્યાખ્યાની ચકાસણી જરૂરી છે.",
  "billing.readiness.auditUnavailable": "ફક્ત-વાંચવા સર્વર તપાસ ઉપલબ્ધ ન હતી. કોઈ પેમેન્ટ કે એકાઉન્ટ ફેરફાર થયો નથી.",
  "billing.dryRun.ariaLabel": "ટેસ્ટ અપગ્રેડ સિમ્યુલેશન",
  "billing.dryRun.title": "Essentials → Business — પ્રેક્ટિસ સિમ્યુલેશન",
  "billing.dryRun.body": "આ બ્રાઉઝરમાં સંપૂર્ણ કાલ્પનિક રેકોર્ડ વાપરીને પ્રસ્તાવિત અપગ્રેડ નિયમોની પ્રેક્ટિસ કરો. આ તમારા વાસ્તવિક TEST — પાયજામા પેન્ટ્સ નમૂનો, તમારું વર્તમાન Business વર્કસ્પેસ, Stripe, ટ્રાયલ, સબસ્ક્રિપ્શન કે ઇન્વેન્ટરીને વાંચતું કે બદલતું નથી.",
  "billing.dryRun.runButton": "સ્થાનિક અપગ્રેડ સિમ્યુલેશન ચલાવો (કોઈ ચાર્જ નહીં)",
  "billing.dryRun.passed": "કાલ્પનિક દૃશ્ય તેની સ્થાનિક તપાસમાં પાસ થયું",
  "billing.dryRun.blocked": "કાલ્પનિક દૃશ્ય બ્લોક થયું",
  "billing.dryRun.example": "ઉદાહરણ: Essentials ($14.99/માસ) → Business ($29.99/માસ), કોઈપણ લાગુ કર પહેલાં.",
  "billing.dryRun.preserved": "તે જ સબસ્ક્રિપ્શન જાળવાયું, એક મૂળ ટ્રાયલ જાળવાઈ, અને સિમ્યુલેટેડ પાયજામા ઇન્વેન્ટરી બદલાયા વિના રહી. ઉદાહરણ ગ્રાહક Essentials પર રહે છે જ્યાં સુધી વાસ્તવિક, પ્રોવાઇડર-પુષ્ટિ ચૂકવેલું રિન્યુઅલ પ્રવેશ બદલવાનું યોગ્ય ન ઠેરવે.",
  "billing.dryRun.limitations": "સ્થાનિક સિમ્યુલેશન Stripe સબસ્ક્રિપ્શન ફેરફાર, પેમેન્ટ, વેબહુક, કર-સહિત ક્વોટ, લાઇવ સબસ્ક્રિપ્શન કે તમારા વાસ્તવિક વ્યવસાય રેકોર્ડનું પરીક્ષણ કરતું નથી.",
