  "import.eyebrow": "ડેટા",
  "import.title": "ઇમ્પોર્ટ કેન્દ્ર",
  "import.subtitleStart": "ત્રણ અલગ સ્પ્રેડશીટ કામગીરી, જેથી ભાવ સુધારો ક્યારેય સ્ટોક રસીદ તરીકે ન આવે. બધું ફક્ત ",
  "import.subtitleRest": " માં જાય છે, અને ડ્રાય રન પાસ થાય ત્યાં સુધી કંઈ લખાતું નથી.",
  "import.createBusinessFirst": "પહેલા વ્યવસાય બનાવો — ઇમ્પોર્ટ કરેલી પ્રોડક્ટ વ્યવસાયની હોય છે.",
  "import.createBusinessFirstShort": "પહેલા વ્યવસાય બનાવો.",
  "import.whatEachDoes": "દરેક કામગીરી શું કરે છે",
  "import.createTitle": "નવી પ્રોડક્ટ બનાવો",
  "import.createDesc": "કેટલોગમાં હજુ ન હોય તેવી પંક્તિઓ ઉમેરે છે. પહેલેથી વપરાશમાં હોય તેવા ડુપ્લિકેટ SKU અને બારકોડ છોડી દેવાય છે, અને શરૂઆતનો સ્ટોક તમે પસંદ કરેલા લોકેશનમાં રસીદ તરીકે આવી શકે છે.",
  "import.updateTitle": "હાલની પ્રોડક્ટ અપડેટ કરો",
  "import.updateDesc": "દરેક પંક્તિને SKU કે રેકોર્ડ ID દ્વારા મેળવે છે અને પ્રસ્તાવિત નવા મૂલ્યની બાજુમાં જૂનું મૂલ્ય બતાવે છે. ખાલી સેલ સાચવેલું મૂલ્ય એકલું છોડે છે સિવાય કે તમે ખાલી સાફ કરવા કહો, અને માત્રા ક્યારેય અડવામાં આવતી નથી.",
  "import.receiveModeTitle": "સ્ટોક મેળવો",
  "import.receiveModeDesc": "આવતી માત્રા એક લોકેશનમાં ઉમેરે છે અને દરેક લાઇન માટે હલનચલન લેજરમાં રસીદ લખે છે. દરેક બેચ ચિહ્નિત થાય છે, જેથી તે જ શીટ બે વાર મેળવી શકાય નહીં.",
  "import.excelNote": "Excel વર્કબુક (.xlsx) સીધી વંચાય છે — વર્કશીટ પસંદ કરો અને કોલમ તમારા માટે મેળવાય છે. કોડ આખા રહે છે: ટેક્સ્ટ તરીકે સાચવેલો UPC તેના અંક અને આગળના શૂન્ય રાખે છે. જે પંક્તિ ઇમ્પોર્ટ થઈ શકે નહીં તે કારણ સાથે સૂચિબદ્ધ થાય છે",
  "import.excelNoteDownload": " અને ફાઇલ તરીકે ડાઉનલોડ થઈ શકે છે.",
  "import.excelNoteFix": ", જેથી તમે તેને સુધારીને ફરી પ્રયાસ કરી શકો.",
  "import.matchColumns": "કોલમ મેળવો",
  "import.columnFallback": "કોલમ {column}",
  "import.ignoreColumn": "આ કોલમ અવગણો",
  "import.mapNameRequired": "એક કોલમને પ્રોડક્ટ નામ સાથે મેળવો — દરેક ઇમ્પોર્ટ કરેલી પંક્તિને નામ જરૂરી છે.",
  "import.receiveMissingMessage": "કોલમને SKU કે રેકોર્ડ ID સાથે, અને એકને મળેલી માત્રા સાથે મેળવો.",
