  "reports.movementsCapped": "ફક્ત સૌથી નવી {cap} લેજર એન્ટ્રી વંચાઈ હતી, તેથી આથી જૂના હલનચલન કુલમાં નથી. વિંડોના ચોક્કસ આંકડા જોવા સમયગાળો સાંકડો કરો.",
  "reports.footnote": "વેચાણ દરેક પ્રોડક્ટની વર્તમાન છૂટક કિંમત વાપરે છે, રસીદ સ્ટોક આવ્યો ત્યારે નોંધાયેલી કિંમત વાપરે છે, અને નુકસાન વર્તમાન એકમ કિંમત વાપરે છે. ખૂટતા પૈસા ક્યારેય શૂન્ય તરીકે ગણાતા નથી; આંકડો જાણી શકાય ત્યાં સુધી ફીલ્ડ ખાલી છોડો. રિપોર્ટ એક દૃશ્ય છે, દસ્તાવેજ નહીં: જ્યારે તમે તેને ચલાવો ત્યારે તમારા રેકોર્ડમાં કંઈ લખાતું નથી.",
