  "print.howToReach": "તમારા પ્રિન્ટર સુધી કેવી રીતે પહોંચવું",
  "print.howIntro": "આ એપ તમારા પોતાના પ્રિન્ટર સાથે જોડાય છે — તે પોતે પ્રિન્ટર નથી. તેના સુધી પહોંચવાની ચાર રીત છે, અને લેબલ બંને પ્લાન પર કોઈપણ રીતે છપાય છે. પેકિંગ સ્લિપ, ખરીદી ઓર્ડર, સપ્લાયર દસ્તાવેજ અને રિપોર્ટ Business-માત્ર છે, કનેક્શન ગમે તે હોય.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "આ પેજથી, ડેસ્કટોપ Chrome કે Edge અને Android Chrome પર: તમારું લેબલ પ્રિન્ટર પસંદ કરો અને લેબલ સીધા તેના પર જાય છે. તે iOS Safari માં કામ કરતું નથી — iPhone પર, Bluetooth પ્રિન્ટિંગ તેના બદલે મોબાઇલ એપ સાથે આવે છે. જે પ્રિન્ટર ફક્ત Zebra ZPL કે Brother ની પોતાની ભાષા બોલે છે તે આ પેજ મોકલે છે તે લેબલ સમજશે નહીં; તેને કામ કરતું કહેતા પહેલા વાસ્તવિક પ્રિન્ટર સામે તપાસવામાં આવે છે.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "તમારી દુકાનના Wi-Fi પર પ્રિન્ટર ઇન્સ્ટોલ કરો, પછી Print બટન વાપરો — તે આ કમ્પ્યુટર પર ઇન્સ્ટોલ કરેલા પ્રિન્ટર દ્વારા, દુકાન નેટવર્ક પર છાપે છે. iPhone પર, AirPrint બિલ્ટ-ઇન છે: તે જ Wi-Fi પરનું AirPrint પ્રિન્ટર પ્રિન્ટ શીટમાં જ દેખાય છે, કોઈ દોરી અને કોઈ એપ જરૂરી નથી, અને એપને કોઈ AirPrint-વિશિષ્ટ કોડ જરૂરી નથી. પ્રિન્ટરે AirPrint સપોર્ટ કરવું જોઈએ (મોટાભાગના નવા કરે છે) અને ફોન અને પ્રિન્ટર તે જ Wi-Fi પર હોવા જોઈએ.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Ethernet દોરીથી પ્રિન્ટરને તમારા દુકાન નેટવર્ક સાથે જોડો, તેને કમ્પ્યુટર પર ઇન્સ્ટોલ કરો, અને Print બટનથી છાપો. Ethernet ડેસ્કટોપ અને કમ્પ્યુટર માર્ગ છે — iPhone Ethernet દોરી વાપરતા નથી.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "તેની દોરીથી પ્રિન્ટરને કમ્પ્યુટરમાં પ્લગ કરો અને Print બટન વાપરો — તે ત્યાં ઇન્સ્ટોલ કરેલા પ્રિન્ટર દ્વારા છાપે છે. USB OTG કેબલવાળા Android ફોન પર, ઉપરનું USB બટન સીધું પ્રિન્ટર સાથે વાત કરે છે. iPhone સીધા USB પર છાપી શકતા નથી — ત્યાં કોઈ WebUSB નથી — તેથી Wi-Fi / AirPrint, કે મોબાઇલ એપથી Bluetooth વાપરો.",
  "print.howCordsLead": "દોરી હજુ iPhone ને સેવા આપે છે, એક પગલું દૂર.",
  "print.howCordsBody": "દુકાન કમ્પ્યુટરમાં પ્લગ કરેલું USB પ્રિન્ટર, કે નેટવર્ક સાથે જોડેલું Ethernet પ્રિન્ટર, તમારા iPhone પર દુકાન Wi-Fi (AirPrint / શેર કરેલું પ્રિન્ટર) પર દેખાય છે — દોરી પ્રિન્ટરને નેટવર્ક પર મજબૂત રીતે મૂકે છે, અને ફોન તેના સુધી વાયરલેસ પહોંચે છે.",
  "print.howOfflineLead": "જો ઇન્ટરનેટ જાય,",
  "print.howOfflineBody": "તો આ પેજ પર પહેલેથી રહેલા લેબલ અને દસ્તાવેજ હજુ છપાય છે — Print બટન, લેબલ PDF, Bluetooth અને USB ને કોઈ કનેક્શન જરૂરી નથી. જેને ઇન્ટરનેટ જરૂરી છે તે પેજ અને તેની પ્રોડક્ટ પહેલી વાર લોડ કરવાનું છે. સંપૂર્ણ ઓફલાઇન મોડ (કોઈ કનેક્શન વિના એપમાં કામ કરવું) અલગ, મોટો બિલ્ડ છે અને અહીં તેનો દાવો નથી.",
