  "settings.businesses.createDescription": "આ તેની પોતાની પ્રોડક્ટ, લોકેશન, સપ્લાયર અને ખરીદી રેકોર્ડ સાથે અલગ વ્યવસાય બનાવે છે. હાલના વ્યવસાય બદલાશે નહીં. મફત પ્રી-લોન્ચ વર્કસ્પેસ બીજી મફત ટ્રાયલ શરૂ કરતા નથી.",
