  "settings.businesses.limitEssentials": "Essentials એક વ્યવસાયની મંજૂરી આપે છે. Business માલિક દીઠ પાંચ વ્યવસાય સુધીની મંજૂરી આપે છે.",
  "settings.businesses.limitFive": "તમે આ એકાઉન્ટ માટે પાંચ-વ્યવસાય મર્યાદા સુધી પહોંચ્યા છો.",
