  "staff.access.noSeatBody": "આ વ્યવસાય માટે તમારા એકાઉન્ટમાં કોઈ સ્ટાફ સીટ નથી, તેથી તેનો સ્ટોક બંધ રહે છે. માલિકને Staff & roles માં તમને ઉમેરવા કહો.",
  "staff.access.noSeatTitle": "આ વ્યવસાય તમારા લોગિન માટે ખુલ્લો નથી",
  "staff.access.pendingBody": "આ વ્યવસાયમાં તમારા ઈમેઈલ માટે આમંત્રણ છે જે સક્રિય થયું નથી. માલિકને તમારી સ્ટાફ સ્થિતિ સક્રિય કરવા કહો. ત્યાં સુધી અહીં કંઈ દેખાતું નથી.",
  "staff.access.pendingTitle": "તમારું આમંત્રણ હજુ સક્રિય નથી",
  "staff.access.signOut": "સાઇન આઉટ",
  "staff.access.suspendedBody": "એડમિનિસ્ટ્રેટરે સક્રિય વ્યવસાય માટે આ સ્ટાફ એકાઉન્ટ સસ્પેન્ડ કર્યું છે. તેમને તમને ફરી સક્રિય કરવા કહો, પછી ફરી સાઇન ઇન કરો.",
  "staff.access.suspendedTitle": "તમારો પ્રવેશ થોભાવેલો છે",
  "staff.addFirst": "પહેલા સ્ટાફ સભ્ય ઉમેરો",
  "staff.addMember": "સ્ટાફ સભ્ય ઉમેરો",
  "staff.emptyBody": "વ્યક્તિ ઉમેરો, તેમને ભૂમિકા અને તેની સાથે જતી પરવાનગીઓ આપો, અને તેમને આ વ્યવસાયમાં સાઇન ઇન કરવા ઈમેઈલથી આમંત્રણ મળે છે.",
  "staff.emptyTitle": "હજુ કોઈ સ્ટાફ નથી",
  "staff.eyebrow": "ટીમ",
  "staff.how.p1": "દરેક સભ્ય પાસે ભૂમિકા અને તેમની પોતાની પરવાનગી યાદી છે, તેથી તમે ભૂમિકાથી શરૂ કરીને નવી ભૂમિકા બનાવ્યા વિના એક વસ્તુ બદલી શકો છો. ભૂમિકા સંપાદિત કરવાથી તેના પર પહેલેથી રહેલા સભ્યો ફરી લખાતા નથી — તેમની ભૂમિકા ડિફોલ્ટ ફરી લાગુ કરવા સભ્ય ખોલો.",
  "staff.how.p2": "કસ્ટમ ભૂમિકા Business સુવિધા છે: Essentials પાંચ બિલ્ટ-ઇન ભૂમિકા વાપરે છે (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "આમંત્રણ ઈમેઈલથી મોકલાય છે. સભ્ય ફક્ત એક વાર સ્વીકારે પછી જ સાઇન ઇન કરી શકે છે, અને આ યાદીમાંથી કોઈને દૂર કરવાથી તેમનું એપ એકાઉન્ટ કાઢી નખાતું નથી.",
  "staff.how.p4": "સ્ટોર તે લોકેશન છે જેને વ્યક્તિ સોંપાયેલ છે. તે તેમના કાર્ડ પર નોંધાય છે; તેઓ શું ખોલી શકે છે તે હજુ તેમની ભૂમિકા અને પરવાનગીઓથી નક્કી થાય છે.",
  "staff.how.p5": "પરવાનગીઓ નક્કી કરે છે કે દરેક વ્યક્તિ શું ખોલી શકે છે: તેમની ભૂમિકાની બહારની મેનુ આઇટમ છુપાય છે, અને બ્લોક કરેલું સરનામું પેજને બદલે “તમારી ભૂમિકા પર નથી” નોટિસ બતાવે છે. ફેરફાર તે વ્યક્તિ આગલી વાર એપ લોડ કરે ત્યારે લાગુ થાય છે; સભ્યને સસ્પેન્ડ કરવાથી તેઓ સંપૂર્ણ બહાર થઈ જાય છે.",
  "staff.how.p6": "એડમિનિસ્ટ્રેટર બધો ડેટા જોઈ અને બદલી શકે છે, એપ વપરાશકર્તા અને ભૂમિકા મેનેજ કરી શકે છે, અને ક્યારેય સ્ટાફ ભૂમિકાથી મર્યાદિત થતા નથી. કોઈ સ્ટાફ રેકોર્ડ વિનાની વ્યક્તિ — નવા વ્યવસાયનો માલિક — સંપૂર્ણ પ્રવેશ રાખે છે.",
  "staff.howTitle": "સ્ટાફ અને ભૂમિકા કેવી રીતે કામ કરે છે",
